var e={"setup.title":`Bienvenue dans Harness Maxxing`,"setup.subtitle":`Choisissez le mot de passe qui protège ce poste de pilotage.`,"setup.token":`Jeton d’installation`,"setup.tokenHint":"Affiché par l’installateur. Lancez `maxxing setup-link` sur le serveur pour le revoir.","setup.tokenRequired":`Le jeton d’installation est requis.`,"setup.badToken":"Ce lien d’installation est invalide, expiré (il vaut 1 heure) ou a déjà servi. Lancez `maxxing setup-link` sur le serveur pour en obtenir un nouveau.","setup.newLink":`Générez un nouveau lien sur le serveur :`,"setup.submit":`Créer le mot de passe`,"setup.footer":`Vous seul pouvez finir cette étape : elle exige le jeton à usage unique.`,"login.title":`Connexion`,"login.subtitle":`Saisissez votre mot de passe Harness Maxxing.`,"login.password":`Mot de passe`,"login.required":`Saisissez votre mot de passe.`,"login.bad":`Mot de passe incorrect.`,"login.throttled":`Trop de tentatives. Patientez un peu avant de réessayer.`,"login.submit":`Se connecter`,"login.forgot":`Mot de passe oublié ?`,"login.forgotHelp":`Réinitialisez-le depuis un terminal sur le serveur :`,"login.passkey":`Se connecter avec une clé d'accès`,"login.orPassword":`ou avec le mot de passe`,"login.passkeyBad":`Cette clé d'accès n'a pas été acceptée. Réessayez, ou utilisez le mot de passe.`,"login.passkeyGone":`Cette clé d'accès a été retirée de ce serveur : votre gestionnaire de mots de passe va la masquer. Utilisez-en une autre, ou le mot de passe.`,"pw.new":`Nouveau mot de passe`,"pw.confirm":`Confirmer le mot de passe`,"pw.hint":`12 caractères minimum. Une longue phrase de passe est idéale.`,"pw.tooShort":`Utilisez au moins 12 caractères.`,"pw.mismatch":`Les mots de passe ne correspondent pas.`,"pw.strength.0":`Vide`,"pw.strength.1":`Trop faible`,"pw.strength.2":`Moyen`,"pw.strength.3":`Bon`,"pw.strength.4":`Solide`,"onb.title":`Premiers pas`,"onb.progress":`Progression de la configuration`,"onb.stepOf":`Étape {n} sur {total}`,"onb.optional":`Facultatif`,"onb.skip":`Passer pour l’instant`,"onb.step.language":`Langue et fuseau`,"onb.step.claude":`Connecter Claude`,"onb.step.workspace":`Vos projets`,"onb.step.telegram":`Telegram`,"onb.step.backup":`Sauvegarde mémoire`,"onb.step.done":`Terminé`,"onb.language.title":`Langue et fuseau horaire`,"onb.language.desc":`Utilisés pour l’interface, les dates et la planification de vos crons.`,"onb.claude.title":`Connecter Claude`,"onb.claude.desc":`Harness Maxxing pilote la CLI officielle Claude Code sur ce serveur, avec votre propre compte ou clé d’API. Rien n’est partagé avec qui que ce soit.`,"onb.claude.defaults":`Valeurs par défaut`,"onb.claude.defaultsDesc":`Modèle et permissions des nouvelles sessions. Modifiables ensuite session par session.`,"onb.claude.later":`Connecter plus tard`,"onb.workspace.title":`Choisissez vos projets de départ`,"onb.workspace.desc":`Des projets prêts à l’emploi selon votre activité : leurs topics connaissent déjà le métier et vous posent quelques questions. Installez-les tous, choisissez, ou passez : vous pourrez les ajouter plus tard dans Réglages -> Modèles.`,"onb.workspace.projectIs":`Projet`,"onb.workspace.projectIsDesc":`Un client, un produit, un domaine de votre vie : « acme », « perso ».`,"onb.workspace.topicIs":`Topic`,"onb.workspace.topicIsDesc":`Un flux de travail à l’intérieur, avec sa mémoire : « blog », « seo », « factures ».`,"onb.workspace.created":`Projet et topic créés`,"onb.workspace.existing":`Vous avez déjà {count} topics`,"onb.workspace.existing#one":`Vous avez déjà {count} topic`,"onb.workspace.existingDesc":`Continuez, ou créez-en un autre ci-dessous.`,"onb.telegram.title":`Parlez à Harness depuis Telegram`,"onb.telegram.desc":`Votre propre bot, un fil par session ouverte : les mêmes conversations que dans le navigateur, sur votre téléphone. Écrivez dans le chat principal pour en démarrer une. Les rapports de crons et les alertes de connexion y arrivent aussi.`,"onb.backup.title":`Sauvegardez votre mémoire`,"onb.backup.desc":`Chaque nuit, vos CLAUDE.md, fichiers mémoire, tâches et crons sont poussés vers un dépôt GitHub privé.`,"onb.done.title":`Tout est prêt`,"onb.done.desc":`Voici ce qui est configuré. Tout reste modifiable dans les Réglages.`,"onb.done.finish":`Ouvrir les sessions`,"onb.summary.password":`Mot de passe`,"onb.summary.claude":`Connexion à Claude`,"onb.summary.workspace":`Premier projet`,"onb.summary.telegram":`Telegram`,"onb.summary.backup":`Sauvegarde mémoire`,"onb.summary.skipped":`passé`,"onb.summary.todo":`à faire`,"onb.tour.sessions":`Plusieurs conversations persistantes par topic, en direct, avec modèle et coût.`,"onb.tour.files":`Parcourez, prévisualisez et modifiez n’importe quel fichier de l’espace de travail.`,"onb.tour.tasks":`Un kanban que Harness peut lire et mettre à jour lui aussi.`,"onb.tour.crons":`Planifiez des commandes shell ou des prompts Harness, avec rapports.`,"onb.tour.telegram":`Reprenez n’importe quelle conversation depuis votre téléphone.`,"onb.tour.docs":`Guides, dépannage et écriture d’extensions.`,"onb.tour.features":`Des pages à activer quand vous en avez besoin : Tâches, Agents, E-mail, Git, Infra, Team.`,"onb.step.profile":`Vous`,"onb.profile.title":`Faire connaissance (facultatif)`,"onb.profile.desc":`Harness Maxxing est gratuit et ne demande aucun compte. Vous pouvez quand même nous dire qui vous êtes : tout est facultatif sur cette page.`,"onb.profile.pseudoDesc":`Votre pseudo dans Harness Maxxing (sur les copies Telegram de vos messages). Modifiable dans Réglages → Profil.`,"onb.profile.counterOn":`Envoyé à api.harness-maxxing.com. Votre pseudo et votre langue ne partent qu'avec un e-mail. Un compteur anonyme (version, système, codes de santé ; ni nom, ni IP) est actif par défaut : il se coupe dans Réglages → Profil.`,"twofa.title":`Validez dans Telegram`,"twofa.subtitle":`La double authentification est activée : ce navigateur a besoin de votre accord.`,"twofa.check":`Regardez Telegram`,"twofa.checkDesc":`Une demande de connexion a été envoyée dans le fil Alertes de votre bot. Appuyez sur Autoriser, ou tapez le code du message ci-dessous.`,"twofa.waiting":`En attente de votre accord… {time}`,"twofa.code":`Code du message`,"twofa.codeLength":`Le code a 6 chiffres.`,"twofa.badCode":`Code incorrect.`,"twofa.codesPaused":`Trop de codes erronés sur ce serveur : utilisez le bouton Autoriser dans Telegram, ou réessayez un code dans une heure`,"twofa.verify":`Valider`,"twofa.trust":`Faire confiance à ce navigateur pendant 30 jours`,"twofa.denied":`Connexion refusée dans Telegram.`,"twofa.expired":`La demande a expiré - reconnectez-vous.`,"twofa.noAnswer":`Telegram ne répond pas ?`,"twofa.noAnswerHelp":`Désactivez la double authentification depuis un terminal sur le serveur, puis connectez-vous avec le mot de passe :`,"twofa.setting":`Double authentification`,"twofa.settingDesc":`Après le mot de passe, un nouveau navigateur attend votre accord dans Telegram (bouton Autoriser ou code). Sortie sans l’interface : maxxing 2fa off sur le serveur.`,"twofa.forget":`Oublier les navigateurs de confiance`,"twofa.forgotten":`Tous les autres navigateurs redemanderont.`,"twofa.enableTitle":`Activer la double authentification`,"twofa.enableDesc":`Validez la demande envoyée dans Telegram : on vérifie que le bot répond avant qu’il protège votre connexion.`,"twofa.offTitle":`Désactiver la double authentification`,"twofa.offDesc":`Saisissez votre mot de passe actuel : Telegram recevra un avertissement.`,"twofa.offConfirm":`Désactiver`,"twofa.enabled":`La double authentification est activée.`,"twofa.needTelegram":`Accord dans Telegram : reliez d'abord un bot Telegram.`,"twofa.linkTelegram":`Réglages → Telegram`,"twofa.titleAny":`Confirmez que c'est vous`,"twofa.subtitleAny":`La double authentification est activée : ce navigateur a besoin d'une deuxième étape.`,"twofa.usePasskey":`Utiliser une clé d'accès`,"twofa.badPasskey":`Cette clé d'accès n'a pas été acceptée. Réessayez, ou utilisez un code.`,"twofa.codeApp":`Code de votre application d'authentification`,"twofa.codeAppOrTelegram":`Code de votre application d'authentification ou du message Telegram`,"twofa.codeRecovery":`Code de récupération`,"twofa.recoveryHint":`Appareil perdu ? Tapez plutôt l'un de vos codes de récupération.`,"twofa.codeFormat":`Tapez le code à 6 chiffres, ou un code de récupération (10 caractères).`,"twofa.expiresIn":`Cette demande expire dans {time}.`,"twofa.lostAll":`Plus accès à aucune de ces méthodes ?`,"twofa.lostAllHelp":`Désactivez la double authentification depuis un terminal sur le serveur, puis connectez-vous avec le mot de passe :`,"twofa.recoveryUsed":`Code de récupération utilisé : il en reste {n}.`,"twofa.recoveryUsedDesc":`Chaque code ne sert qu'une fois. Créez-en de nouveaux dans Réglages -> Sécurité quand il en reste peu.`,"twofa.cardDesc":`Après le mot de passe, un nouveau navigateur a besoin d'une deuxième étape : une clé d'accès, un code d'une application d'authentification, ou votre accord dans Telegram. Porte de sortie sans l'interface web : maxxing 2fa off sur le serveur.`,"twofa.tgRow":`Accord dans Telegram`,"twofa.on":`Activée`,"twofa.remove":`Retirer`,"twofa.rename":`Renommer`,"twofa.app":`Application d'authentification`,"twofa.appDesc":`Un code à 6 chiffres qui change toutes les 30 secondes, depuis Authy, Google Authenticator, Microsoft Authenticator, Aegis, Bitwarden, 1Password…`,"twofa.appSetup":`Configurer`,"twofa.appSetupTitle":`Configurer une application d'authentification`,"twofa.appSetupDesc":`Scannez le QR code avec l'application (ou ajoutez la clé à la main), puis tapez le code qu'elle affiche.`,"twofa.appOpen":`Ouvrir dans une application d'authentification de cet appareil`,"twofa.appQr":`QR code à scanner avec l'application d'authentification`,"twofa.appManual":`Impossible de scanner ? Ajoutez cette clé à la main :`,"twofa.appManualHint":`Type : basé sur le temps (TOTP), 6 chiffres, toutes les 30 secondes.`,"twofa.appCode":`Code affiché par l'application`,"twofa.appConfirm":`Activer`,"twofa.appBadCode":`Code incorrect. Vérifiez que l'heure de votre téléphone est réglée automatiquement, puis tapez le code actuel.`,"twofa.setupExpired":`La configuration a expiré : fermez cette fenêtre et recommencez.`,"twofa.appAdded":`L'application d'authentification est activée.`,"twofa.appOffTitle":`Retirer l'application d'authentification`,"twofa.appOffDesc":`Tapez votre mot de passe actuel. Ses codes ne fonctionneront plus.`,"twofa.appRemoved":`Application d'authentification retirée.`,"twofa.passkeys":`Clés d'accès (passkeys)`,"twofa.passkeysDesc":`Votre empreinte, votre visage, un code PIN ou une clé de sécurité, gardés par votre appareil ou votre gestionnaire de mots de passe (Bitwarden, 1Password, trousseau iCloud, Gestionnaire de mots de passe de Google, Windows Hello, YubiKey…). Une clé d'accès ne fonctionne que sur l'adresse où elle a été créée.`,"twofa.passkeyAdd":`Ajouter une clé d'accès`,"twofa.passkeyName":`Nom`,"twofa.passkeyAdded":`Clé d'accès ajoutée : {name}.`,"twofa.passkeyExists":`Cet appareil a déjà une clé d'accès pour ce serveur.`,"twofa.passkeyRefused":`La clé d'accès n'a pas pu être ajoutée. Réessayez.`,"twofa.passkeyNeedsName":`Les clés d'accès demandent une adresse avec un nom (votre domaine, en https) : les navigateurs les refusent sur une adresse IP. Ouvrez cette page par votre domaine pour en ajouter une ; les codes fonctionnent partout.`,"twofa.passkeyNeedsHttps":`Les clés d'accès demandent une adresse en https. Ouvrez cette page en https pour en ajouter une ; les codes fonctionnent partout.`,"twofa.passkeyUnsupported":`Ce navigateur ne sait pas utiliser les clés d'accès.`,"twofa.passkeyUsed":`utilisée le {date}`,"twofa.passkeyNever":`pas encore utilisée`,"twofa.passkeyOffTitle":`Retirer « {name} »`,"twofa.passkeyOffDesc":`Tapez votre mot de passe actuel. Vous pourrez aussi la supprimer ensuite de votre appareil ou de votre gestionnaire de mots de passe.`,"twofa.goneTitle":`« {name} » retirée de Harness`,"twofa.goneManual":`Elle reste enregistrée dans votre gestionnaire de mots de passe ou votre appareil, que ce navigateur ne sait pas prévenir : supprimez-la aussi là-bas, sinon elle continuera d'être proposée (et refusée).`,"twofa.goneSignaled":`Votre navigateur a demandé à votre gestionnaire de mots de passe de la masquer. Si elle y apparaît encore, supprimez-la à la main :`,"twofa.goneStep1":`Ouvrez votre gestionnaire de mots de passe (Bitwarden, 1Password…) ou les clés d'accès de votre appareil (Windows Hello, trousseau iCloud, Gestionnaire de mots de passe de Google).`,"twofa.goneStep2":`Cherchez la clé d'accès de {host}.`,"twofa.goneStep3":`Supprimez cette clé d'accès (pas vos autres entrées pour ce site).`,"twofa.confirmPasskey":`Confirmer avec une clé d'accès`,"twofa.offerTitle":`Connectez-vous plus vite la prochaine fois`,"twofa.offerDesc":`Créez une clé d'accès : votre empreinte, votre visage, un code PIN ou votre gestionnaire de mots de passe ouvriront Harness sans le mot de passe. Vous pourrez la désactiver dans Réglages -> Sécurité.`,"twofa.offerCreate":`Créer une clé d'accès`,"twofa.offerLater":`Plus tard`,"twofa.offerNever":`Ne plus proposer`,"twofa.offerDone":`La prochaine fois, appuyez sur Se connecter avec une clé d'accès.`,"twofa.offerAppTitle":`Protégez votre connexion`,"twofa.offerAppDesc":`Les clés d'accès ne peuvent pas fonctionner sur cette adresse (une adresse IP ou du http simple). Ajoutez plutôt une application d'authentification : après le mot de passe, un code à 6 chiffres de votre téléphone ou de votre gestionnaire de mots de passe sera demandé.`,"twofa.passkeyLogin":`Connexion par clé d'accès seule`,"twofa.passkeyLoginDesc":`Sur la page de connexion, une clé d'accès remplace le mot de passe et la deuxième étape (elle vérifie votre empreinte, votre visage ou votre code PIN). Désactivée : la clé ne sert que de deuxième étape.`,"twofa.passkeyLoginOnTitle":`Connexion par clé d'accès seule`,"twofa.passkeyLoginOnDesc":`Tapez votre mot de passe actuel. Vos clés d'accès ouvriront ensuite Harness sans le mot de passe.`,"twofa.recovery":`Codes de récupération`,"twofa.recoveryLeft":`il en reste {n}`,"twofa.recoveryDesc":`Des codes à usage unique pour vous connecter si vous perdez votre téléphone ou vos clés d'accès. Gardez-les en lieu sûr, ailleurs que sur ce serveur.`,"twofa.recoveryNew":`Nouveaux codes`,"twofa.recoveryNewTitle":`Créer de nouveaux codes de récupération`,"twofa.recoveryNewDesc":`Tapez votre mot de passe actuel. Les anciens codes ne fonctionneront plus.`,"twofa.recoveryTitle":`Vos codes de récupération`,"twofa.recoveryShownOnce":`Enregistrez-les maintenant (gestionnaire de mots de passe, impression) : ils ne seront plus affichés. Chacun permet une connexion quand vos autres méthodes sont inutilisables.`,"twofa.recoveryCopy":`Tout copier`,"twofa.recoveryDownload":`Télécharger`,"twofa.recoverySaved":`Je les ai enregistrés`,"twofa.recoveryFileHead":`Harness Maxxing - codes de récupération (chacun ne sert qu'une fois)`,"onb.workspace.own":`Ou créez votre propre projet`,"onb.step.import":`Import`,"onb.import.title":`Vous venez d’un autre agent ?`,"onb.import.desc":`Récupérez tout ce que votre agent actuel sait - projets, topics, mémoire, skills - en deux minutes. Ou passez et partez de zéro.`,"onb.import.skip":`Partir de zéro`,"onb.step.features":`Vos pages`,"onb.features.title":`Qu’allez-vous utiliser ?`,"onb.features.desc":`Sessions, Fichiers et Notifications sont toujours là. Allumez les autres pages dont vous avez besoin maintenant : tout se change ensuite dans Réglages → Fonctionnalités.`,"onb.done.notify":`Me prévenir quand une session se termine`,"onb.done.notifyDesc":`Une notification du navigateur quand Claude a fini et que cet onglet n’est pas devant.`};export{e as default};